from pathlib import Path
import json,re,csv,shutil
ROOT=Path(__file__).resolve().parent
WEEKS=[]
def week(title,phase,area,inputs,calculation,requirements,gate,stage,rows):
 entries=[]
 for line in rows.strip().splitlines():
  parts=[p.strip() for p in line.split(' || ')]
  assert len(parts)==5,(title,line,len(parts))
  entries.append(parts)
 assert len(entries)==7,(title,len(entries))
 WEEKS.append(dict(title=title,phase=phase,area=area,inputs=inputs,calculation=calculation,requirements=requirements,gate=gate,stage=stage,entries=entries))

